/**
 * The speakers section of `Settings`.
 */
export type SpeakerSettings = { 
/**
 * Name speakers from voice profiles and the calendar after each
 * meeting (the `identify_speakers` stage). On by default.
 */
autoIdentify: boolean; 
/**
 * When a voice counts as a known person.
 */
thresholds: IdentifyThresholds }
/**
 * How the user left a step.
 */
export type StepOutcome = 
/**
 * The user went through it.
 */
"done" | 
/**
 * The user skipped it; Settings can resume it.
 */
"skipped"
/**
 * Identifies a tag.
 */
export type TagId = string & { readonly __brand: "TagId" }
/**
 * A provider and model, chosen by a route or pinned by the caller.
 */
export type Target = { 
/**
 * Who serves the call.
 */
provider: ProviderId; 
/**
 * The provider's model ID.
 */
model: string }
/**
 * Identifies a note template (NOT-04).
 * 
 * Built-in templates have readable, stable slugs (`one_on_one`), so a
 * release can upgrade them in place; the user's own templates get a
 * UUIDv7 from [`TemplateId::generate`]. Both are opaque text to the
 * database (`templates.id`).
 */
export type TemplateId = string & { readonly __brand: "TemplateId" }
/**
 * The templates section of `Settings`.
 */
export type TemplateSettings = { 
/**
 * The template a meeting gets when the user has not chosen one and no
 * template's auto rules match. `None` is "Auto": the LLM classifier may
 * suggest one, and otherwise the General template is used. A default
 * that names a deleted template falls back the same way.
 */
defaultTemplate: TemplateId | null }
/**
 * The colour theme (PARITY_PLAN §3B: follow the system by default).
 */
export type Theme = 
/**
 * Match macOS's appearance.
 */
"system" | 
/**
 * Always light.
 */
"light" | 
/**
 * Always dark.
 */
"dark"
/**
 * A local speech-to-text engine. New installs use [`Self::ParakeetUnified`];
 * the others stay available under "Advanced".
 */
export type TranscriptionEngine = 
/**
 * NVIDIA Parakeet Unified EN 0.6B over transcribe.cpp (CAP-01): streams
 * live text while recording. Its `model` is a catalog file ID, or empty
 * for the quant this Mac's memory suits.
 */
"parakeet_unified" | 
/**
 * NVIDIA Parakeet TDT over ONNX Runtime.
 */
"parakeet" | 
/**
 * whisper.cpp. The legacy settings called it `localWhisper`.
 */
"whisper"
/**
 * The transcription section of `Settings`.
 */
export type TranscriptionSettings = { 
/**
 * The engine that transcribes recordings.
 */
engine: TranscriptionEngine; 
/**
 * The engine's model; empty means the engine's recommended model.
 * Parakeet Unified takes a catalog file ID such as
 * `parakeet-unified-en-0.6b-Q8_0` (the file name without `.gguf`; the
 * file name itself is accepted too, see `ModelFileId::from_setting`);
 * Parakeet TDT a model folder such as `parakeet-tdt-0.6b-v3-int8`;
 * Whisper a model name such as `large-v3-turbo`.
 */
model: string; 
/**
 * "Live transcription" (CAP-08): on, the transcript appears while the
 * meeting is recorded; off, only audio is recorded (no engine runs) and
 * the transcript is written after the meeting.
 */
liveTranscription: boolean; 
/**
 * "High-accuracy re-pass after meeting" (CAP-08): transcribe the whole
 * recording again with full context and replace the live transcript,
 * keeping its speakers.
 */
highAccuracyRepass: boolean }
/**
 * The UI section of `Settings`.
 */
export type UiSettings = { 
/**
 * The colour theme.
 */
theme: Theme; 
/**
 * Show the transcription confidence indicator next to transcript lines.
 */
showConfidenceIndicator: boolean; 
/**
 * The transcript pane's share of the meeting page's width.
 */
transcriptPaneRatio: number; 
/**
 * The Meetings page's filter and open tab, kept across launches.
 */
meetingsList: MeetingsListPrefs }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
